import pytest

import calibration_target

pytestmark = pytest.mark.verification_kind("unit")


@pytest.mark.verifies("TREQ_CALIBRATION_SUMMARY[revision==1]")
def test_summary_hides_sensitive_data() -> None:
    value = "classified_payload"
    record = calibration_target.Record(name="database", secret=value, level=0)
    assert record.summary() == {"name": "database"}
